public class Zoo {
    private Animal[] animals;
    private int count;

    public Zoo(int max) {
        this.animals = new Animal[max];
        this.count = 0;
    }

    public void add(Animal a) {
        if (count < animals.length) {
            animals[count] = a;
            count++;
        }
    }

    public int getCount() {
        return count;
    }

    public int getSize() {
        return animals.length;
    }

    public Animal getAnimal(int i) {
        return animals[i];
    }
}

