public String say() {
    return super.say() + " של " + owner.getName();
}

public int countDogs() {
    int n = 0;
    for (int i = 0; i < count; i++) {
        if (animals[i] instanceof Dog) {
            n++;
        }
    }
    return n;
}

public String findOwner(String dogName) {
    for (int i = 0; i < count; i++) {
        if (animals[i] instanceof Labrador && animals[i].getName().equals(dogName)) {
            Labrador lab = (Labrador) animals[i];
            return lab.getOwner().getName();
        }
    }
    return null;
}

public static Zoo onlyMammals(Zoo z) {
    Zoo res = new Zoo(z.getSize());
    for (int i = 0; i < z.getCount(); i++) {
        if (z.getAnimal(i) instanceof Mammal) {
            res.add(z.getAnimal(i));
        }
    }
    return res;
}

