Person hila = new Person("Hila");
Labrador toto = new Labrador("Toto", 2.5, 4, hila);
System.out.println("סעיף א, בדיקה 1: " + check(toto.say(), "כלב של Hila"));
Animal max = new Labrador("Max", 1.5, 2, new Person("Yoav"));
System.out.println("סעיף א, בדיקה 2 (דרך הפניה מטיפוס Animal): " + check(max.say(), "כלב של Yoav"));
Zoo zoo = new Zoo(8);
zoo.add(new Animal("Nemo"));
zoo.add(toto);
zoo.add(new Boxer("Rexy", 3.0, 3, "house"));
zoo.add(new Mammal("Numa", 2.0));
zoo.add(max);
zoo.add(new Dog("Lucky", 1.0, 2));
System.out.println("סעיף ב, בדיקה 1: " + check(zoo.countDogs(), 4));
System.out.println("סעיף ב, בדיקה 2 (גן ריק): " + check(new Zoo(3).countDogs(), 0));
System.out.println("סעיף ג, בדיקה 1: " + check(zoo.findOwner("Max"), "Yoav"));
System.out.println("סעיף ג, בדיקה 2: " + check(zoo.findOwner("Toto"), "Hila"));
System.out.println("סעיף ג, בדיקה 3 (Rexy הוא בוקסר): " + check(zoo.findOwner("Rexy"), "null"));
System.out.println("סעיף ג, בדיקה 4 (אין חיה בשם הזה): " + check(zoo.findOwner("Bob"), "null"));
Zoo mammals = onlyMammals(zoo);
System.out.println("סעיף ד, בדיקה 1: " + check(mammals.getCount(), 5));
System.out.println("סעיף ד, בדיקה 2: " + check(mammals.getAnimal(0).getName(), "Toto"));
System.out.println("סעיף ד, בדיקה 3: " + check(mammals.getSize(), 8));
System.out.println("סעיף ד, בדיקה 4 (הגן המקורי לא השתנה): " + check(zoo.getCount(), 6));

